// conv_fused: host dispatch + autograd. Kernels live in conv_fused.cuh and are
// instantiated one config per TU in csrc/inst/conv_fused_<id>.cu (generated by configs.py)
// to keep nvcc memory low and the build parallel.
#include "conv_fused.cuh"

namespace jet_mlip {
namespace {
using namespace cf;
#define JET_EXTERN(ID, CFG) \
  extern template void launch<float, CFG, EPL_OF<float, CFG, false>, false>(const Args<float>&); \
  extern template void launch<float, CFG, EPL_OF<float, CFG, true>, true>(const Args<float>&); \
  extern template void launch<double, CFG, EPL_OF<double, CFG, false>, false>(const Args<double>&); \
  extern template void launch<double, CFG, EPL_OF<double, CFG, true>, true>(const Args<double>&);
}  // namespace
namespace cf {
JET_FOREACH_CONFIG(JET_EXTERN)
// conv_first.cu: scalar-only input (first layer) on the radial table; false = not that case, take the generic kernel
bool first_layer(int64_t cfg_id, const Args<float>& a, bool bwd);
inline bool first_layer(int64_t, const Args<double>&, bool) { return false; }
}  // namespace cf
#undef JET_EXTERN
namespace {

void check_inputs(const at::Tensor& x, const at::Tensor& vec, const at::Tensor& src, const at::Tensor& rowptr,
                  const at::Tensor& perm, const at::Tensor& w1, const at::Tensor& w2, const at::Tensor& w3,
                  const at::Tensor& coeffs, const std::optional<at::Tensor>& table,
                  const std::optional<at::Tensor>& tabidx, int in_dim, int nw) {
  for (const auto* t : {&x, &vec, &src, &rowptr, &perm, &w1, &w2, &w3, &coeffs})
    TORCH_CHECK(t->is_cuda() && t->is_contiguous(), "conv_fused: all inputs must be contiguous CUDA tensors");
  for (const auto* t : {&vec, &w1, &w2, &w3, &coeffs})
    TORCH_CHECK(t->scalar_type() == x.scalar_type(), "conv_fused: dtype mismatch");
  for (const auto* t : {&src, &rowptr, &perm})
    TORCH_CHECK(t->scalar_type() == at::kInt, "conv_fused: src/rowptr/perm must be int32");
  TORCH_CHECK(x.dim() == 2 && x.size(1) == in_dim, "conv_fused: x must be (N_all, ", in_dim, ")");
  TORCH_CHECK(vec.dim() == 2 && vec.size(1) == 3 && src.numel() == vec.size(0) && perm.numel() == vec.size(0),
              "conv_fused: edge_vec (E,3), src (E), perm (E)");
  TORCH_CHECK(rowptr.numel() >= 1 && rowptr.numel() - 1 <= x.size(0), "conv_fused: rowptr must be (N_out+1), N_out <= N_all");
  TORCH_CHECK(w1.sizes() == at::IntArrayRef({NB, NH}) && w2.sizes() == at::IntArrayRef({NH, NH})
              && w3.sizes() == at::IntArrayRef({NH, nw}) && coeffs.numel() == NB,
              "conv_fused: w1 (8,64), w2 (64,64), w3 (64,", nw, "), coeffs (8)");
  if (table.has_value()) {
    TORCH_CHECK(table->is_cuda() && table->is_contiguous() && table->scalar_type() == x.scalar_type(),
                "conv_fused: table must be a contiguous CUDA tensor of x's dtype");
    TORCH_CHECK(x.scalar_type() == at::kFloat, "conv_fused: the radial table is fp32 only");
    TORCH_CHECK((table->dim() == 2 || table->dim() == 3) && table->size(-2) >= 2 && table->size(-1) == 4 * nw
                && reinterpret_cast<uintptr_t>(table->data_ptr()) % 16 == 0,
                "conv_fused: table must be ([ntables,] n >= 2, 4*", nw, ") = [k][c][W, dW/dr, dW_node/h, dW/dr(k+1)], 16 B aligned "
                "(models deployed with v0.3.0 hold (n, 3*nw): deploy them again)");
    if (tabidx.has_value()) {
      TORCH_CHECK(table->dim() == 3 && tabidx->is_cuda() && tabidx->scalar_type() == at::kInt
                  && tabidx->numel() == vec.size(0),
                  "conv_fused: table_idx must be int32 (E,) on CUDA and the table 3-D");
    } else {
      TORCH_CHECK(table->dim() == 2, "conv_fused: a 3-D table needs table_idx");
    }
  }
}

at::Tensor conv_fused_cuda(const at::Tensor& x, const at::Tensor& vec, const at::Tensor& src,
                           const at::Tensor& rowptr, const at::Tensor& perm, const at::Tensor& w1,
                           const at::Tensor& w2, const at::Tensor& w3, const at::Tensor& coeffs,
                           double denom, double r_on, double r_cut, double cst, int64_t cfg_id,
                           const std::optional<at::Tensor>& table, bool split_bwd,
                           const std::optional<at::Tensor>& tabidx) {
  (void)split_bwd;   // backward-only option, carried by the autograd node
  const c10::cuda::CUDAGuard guard(x.device());
  const auto& tab = table;
  at::Tensor out;
  switch (cfg_id) {
#define JET_CASE(ID, CFG)                                                                     \
  case ID: {                                                                                      \
    check_inputs(x, vec, src, rowptr, perm, w1, w2, w3, coeffs, tab, tabidx, CFG::IN_DIM, CFG::NW);   \
    out = at::empty({rowptr.numel() - 1, CFG::OUT_DIM}, x.options());                              \
    if (out.numel() == 0) return out;                                                              \
    AT_DISPATCH_FLOATING_TYPES(x.scalar_type(), "conv_fused", [&] {                                \
      auto a = make_args<scalar_t>(x, vec, src, rowptr, perm, w1, w2, w3, coeffs, denom, r_on, r_cut, cst, tab, tabidx); \
      a.out = out.data_ptr<scalar_t>();                                                            \
      if (!first_layer(ID, a, false)) launch<scalar_t, CFG, EPL_OF<scalar_t, CFG, false>, false>(a); \
    });                                                                                            \
    break;                                                                                         \
  }
    JET_FOREACH_CONFIG(JET_CASE)
#undef JET_CASE
    default: TORCH_CHECK(false, "conv_fused: unknown config id ", cfg_id);
  }
  return out;
}

std::tuple<at::Tensor, at::Tensor> conv_fused_bwd_cuda(
    const at::Tensor& gout, const at::Tensor& x, const at::Tensor& vec, const at::Tensor& src,
    const at::Tensor& rowptr, const at::Tensor& perm, const at::Tensor& w1, const at::Tensor& w2,
    const at::Tensor& w3, const at::Tensor& coeffs, double denom, double r_on, double r_cut, double cst,
    int64_t cfg_id, const std::optional<at::Tensor>& table, bool need_grad_x, bool split_bwd,
    const std::optional<at::Tensor>& tabidx) {
  const c10::cuda::CUDAGuard guard(x.device());
  auto gx = need_grad_x ? at::zeros_like(x) : at::Tensor();   // undefined when the caller does not need it
  auto gvec = at::zeros_like(vec);
  auto g = gout.contiguous();
  const auto& tab = table;
  // split backward (exact MLP only; the table has no MLP): grad_H2 per edge, E x NH x sizeof(T) transient bytes,
  // freed with this scope (the caching allocator hands the block to the next layer). A single-path-group layer
  // runs the MLP backward once anyway: the second kernel would only add work, so it stays on the recompute path.
  at::Tensor gh2, gshb;   // gshb: table bwd per-edge grad_sh / grad_r rows, E x (SH_DIM + 1)
  switch (cfg_id) {
#define JET_CASE(ID, CFG)                                                                     \
  case ID: {                                                                                      \
    check_inputs(x, vec, src, rowptr, perm, w1, w2, w3, coeffs, tab, tabidx, CFG::IN_DIM, CFG::NW);   \
    TORCH_CHECK(g.is_cuda() && g.scalar_type() == x.scalar_type()                                  \
                && g.sizes() == at::IntArrayRef({rowptr.numel() - 1, CFG::OUT_DIM}), "conv_fused_bwd: bad grad_out"); \
    if (g.numel() == 0) break;                                                                     \
    AT_DISPATCH_FLOATING_TYPES(x.scalar_type(), "conv_fused_bwd", [&] {                            \
      auto a = make_args<scalar_t>(x, vec, src, rowptr, perm, w1, w2, w3, coeffs, denom, r_on, r_cut, cst, tab, tabidx); \
      a.gout = g.data_ptr<scalar_t>(); a.gx = need_grad_x ? gx.data_ptr<scalar_t>() : nullptr;        \
      a.gvec = gvec.data_ptr<scalar_t>();                                                         \
      if (split_bwd && !tab.has_value() && Groups<scalar_t, CFG, EPL_OF<scalar_t, CFG, true>, true>::NG > 1) \
        gh2 = at::zeros({vec.size(0), NH}, x.options());                                         \
      a.gh2 = gh2.defined() ? gh2.data_ptr<scalar_t>() : nullptr;                                 \
      if (tab.has_value()) gshb = at::zeros({vec.size(0), CFG::SH_DIM + 1}, x.options());          \
      a.gshb = gshb.defined() ? gshb.data_ptr<scalar_t>() : nullptr;                              \
      if (!first_layer(ID, a, true)) launch<scalar_t, CFG, EPL_OF<scalar_t, CFG, true>, true>(a); \
    });                                                                                            \
    break;                                                                                         \
  }
    JET_FOREACH_CONFIG(JET_CASE)
#undef JET_CASE
    default: TORCH_CHECK(false, "conv_fused_bwd: unknown config id ", cfg_id);
  }
  return {gx, gvec};
}

// ---- autograd (first order only; the backward op itself is not differentiable) ------------
struct ConvFusedFn : public torch::autograd::Function<ConvFusedFn> {
  static at::Tensor forward(torch::autograd::AutogradContext* ctx, const at::Tensor& x, const at::Tensor& vec,
                            const at::Tensor& src, const at::Tensor& rowptr, const at::Tensor& perm,
                            const at::Tensor& w1, const at::Tensor& w2, const at::Tensor& w3,
                            const at::Tensor& coeffs, double denom, double r_on, double r_cut, double cst,
                            int64_t cfg_id, const std::optional<at::Tensor>& table, bool split_bwd,
                            const std::optional<at::Tensor>& tabidx) {
    ctx->save_for_backward({x, vec, src, rowptr, perm, w1, w2, w3, coeffs,
                            table.has_value() ? *table : at::Tensor(),
                            tabidx.has_value() ? *tabidx : at::Tensor()});
    ctx->saved_data["s"] = std::vector<double>{denom, r_on, r_cut, cst};
    ctx->saved_data["cfg"] = cfg_id;
    ctx->saved_data["split"] = split_bwd;
    at::AutoDispatchBelowADInplaceOrView guard;
    return conv_fused_cuda(x, vec, src, rowptr, perm, w1, w2, w3, coeffs, denom, r_on, r_cut, cst, cfg_id, table,
                           split_bwd, tabidx);
  }
  static torch::autograd::variable_list backward(torch::autograd::AutogradContext* ctx,
                                                 torch::autograd::variable_list gouts) {
    const auto s = ctx->get_saved_variables();
    const auto sc = ctx->saved_data["s"].toDoubleVector();
    // Inference kernel: only x and edge_vec get gradients. needs_input_grad is per backward
    // task, so autograd.grad(E, pos) with trainable weights passes; a loss.backward() that
    // needs the weight / coefficient grads errors instead of silently getting none.
    TORCH_CHECK(!ctx->needs_input_grad({{5, 9}}),
                "conv_fused: no gradient for the radial weights / Bessel coefficients in eval mode; "
                "training is not supported (a JET_TRAIN=1 build has the unsupported train-mode tp3 path)");
    at::Tensor gx, gvec;
    if (gouts[0].defined()) {
      at::NoGradGuard no_grad;   // no double backward
      std::optional<at::Tensor> table, tabidx;
      if (s[9].defined()) table = s[9];
      if (s[10].defined()) tabidx = s[10];
      std::tie(gx, gvec) = conv_fused_bwd_cuda(gouts[0], s[0], s[1], s[2], s[3], s[4], s[5], s[6], s[7], s[8],
                                               sc[0], sc[1], sc[2], sc[3], ctx->saved_data["cfg"].toInt(), table,
                                               ctx->needs_input_grad(0), ctx->saved_data["split"].toBool(), tabidx);
    }
    return {gx, gvec, at::Tensor(), at::Tensor(), at::Tensor(), at::Tensor(), at::Tensor(), at::Tensor(),
            at::Tensor(), at::Tensor(), at::Tensor(), at::Tensor(), at::Tensor(), at::Tensor(), at::Tensor(), at::Tensor(),
            at::Tensor()};
  }
};

at::Tensor conv_fused_autograd(const at::Tensor& x, const at::Tensor& vec, const at::Tensor& src,
                               const at::Tensor& rowptr, const at::Tensor& perm, const at::Tensor& w1,
                               const at::Tensor& w2, const at::Tensor& w3, const at::Tensor& coeffs,
                               double denom, double r_on, double r_cut, double cst, int64_t cfg_id,
                               const std::optional<at::Tensor>& table, bool split_bwd,
                               const std::optional<at::Tensor>& tabidx) {
  return ConvFusedFn::apply(x, vec, src, rowptr, perm, w1, w2, w3, coeffs, denom, r_on, r_cut, cst, cfg_id, table,
                            split_bwd, tabidx);
}

// fp32 path-group counts of a config: [fwd, bwd, fwd table, bwd table, SMEM_MAX bytes, blocks per SM of the fwd table
// kernel, of the bwd table kernel (tab_kb)]. Introspection only (docs, tests, checking what a bigger shared-memory
// limit buys on another GPU).
std::vector<int64_t> config_groups(int64_t cfg_id) {
  switch (cfg_id) {
#define JET_GROUPS(ID, CFG)                                                                    \
  case ID: {                                                                                       \
    constexpr int EF = EPL_OF<float, CFG, false>, EB = EPL_OF<float, CFG, true>;                   \
    constexpr int TF = epl_tab<CFG, false>(), TB = epl_tab<CFG, true>();                           \
    return {Groups<float, CFG, EF, false>::NG, Groups<float, CFG, EB, true>::NG,                   \
            Groups<float, CFG, TF, false, true>::NG, Groups<float, CFG, TB, true, true>::NG, SMEM_MAX, \
            tab_kb<CFG, TF, false>(), tab_kb<CFG, TB, true>()};                                    \
  }
    JET_FOREACH_CONFIG(JET_GROUPS)
#undef JET_GROUPS
    default: TORCH_CHECK(false, "jet: bad config id ", cfg_id);
  }
}

}  // namespace
}  // namespace jet_mlip

TORCH_LIBRARY_FRAGMENT(jet_mlip, m) {
  m.def("config_groups(int cfg_id) -> int[]", &jet_mlip::config_groups);
  m.def("conv_fused(Tensor x, Tensor edge_vec, Tensor src, Tensor rowptr, Tensor perm, Tensor w1, Tensor w2, "
        "Tensor w3, Tensor coeffs, float denominator, float r_on, float r_cut, float act_cst, int cfg_id, "
        "Tensor? table=None, bool split_bwd=True, Tensor? table_idx=None) -> Tensor");
  m.def("conv_fused_bwd(Tensor grad_out, Tensor x, Tensor edge_vec, Tensor src, Tensor rowptr, Tensor perm, "
        "Tensor w1, Tensor w2, Tensor w3, Tensor coeffs, float denominator, float r_on, float r_cut, "
        "float act_cst, int cfg_id, Tensor? table=None, bool need_grad_x=True, bool split_bwd=True, "
        "Tensor? table_idx=None) -> (Tensor, Tensor)");
}
TORCH_LIBRARY_IMPL(jet_mlip, CUDA, m) {
  m.impl("conv_fused", &jet_mlip::conv_fused_cuda);
  m.impl("conv_fused_bwd", &jet_mlip::conv_fused_bwd_cuda);
}
TORCH_LIBRARY_IMPL(jet_mlip, Autograd, m) {
  m.impl("conv_fused", &jet_mlip::conv_fused_autograd);
}
